/**
 * @param {$T.obj | null} obj struct obj *
 * @param {$T.obj | null} how struct obj *
 * @param {number} voluntary boolean
 * @returns {Promise<void>}
 */
export async function wielding_corpse(obj, how, voluntary) {   // do_wear.c:608
    let kbuf = new Int8Array(256), hbuf = new Int8Array(256);
    /* uwep, potentially a wielded cockatrice corpse */
    /* gloves or dragon armor or Null (resist timeout) */
    /* True: taking protective armor off on purpose */
    if (!obj || obj.otyp !== CORPSE || $G.uarmg) {
        return;
    }
    /* note: can't dual-wield with non-weapons/weapon-tools so u.twoweap
       will always be false if uswapwep happens to be a corpse */
    if (obj !== $G.uwep && (obj !== $G.uswapwep || !u.twoweap)) {
        return;
    }
    if (touch_petrifies($c.relem(mons, obj.corpsenm)) && !Stone_resistance()) {
        await You($C`%s %s in your bare %s.`,
            how && is_gloves(how) ? $C`now wield` : $C`are wielding`,
            await corpse_xname(obj, null, CXN.ARTICLE),
            await makeplural(await body_part(HAND)));
        /* "removing" ought to be "taking off" but that makes the
           tombstone text more likely to be truncated */
        if (how) {
            $c.sprintf(new $c.Ptr(hbuf, 0), $C`%s %s`, voluntary ? $C`removing` : $C`losing`, how.oclass === ARMOR_CLASS && objects[how.otyp].oc_subtyp === ARM_GLOVES ? gloves_simple_name(how) : strsubst(await simpleonames(how), $C`set of `, $C``));
        } else {
            $c.strcpy(new $c.Ptr(hbuf, 0), $C`resistance timing out`);
        }
        nh_snprintf($C`wielding_corpse`, 636, new $c.Ptr(kbuf, 0), 256, $C`%s while wielding %s`, new $c.Ptr(hbuf, 0), await killer_xname(obj));
        await instapetrify(new $c.Ptr(kbuf, 0));
        /* life-saved or got poly'd into a stone golem; can't continue
           wielding cockatrice corpse unless have now become resistant */
        if (!Stone_resistance()) {
            await remove_worn_item(obj, FALSE);
        }
    }
}
/**
 * @returns {Promise<number>} int
 */
export async function Gloves_off() {   // do_wear.c:646
    let $t1;
    const gloves = $G.uarmg;   /* needed after uarmg has been set to Null */
    const oldprop = $c.and64(u.uprops[objects[$G.uarmg.otyp].oc_oprop].extrinsic, ~W.ARMG);
    const on_purpose = !svc.context.mon_moving && !$G.uarmg.in_use ? 1 : 0;
    svc.context.takeoff.mask = $c.and64(svc.context.takeoff.mask, ~W.ARMG);
    switch ($G.uarmg.otyp) {
        case LEATHER_GLOVES:
            break;
        case GAUNTLETS_OF_FUMBLING:
            if (!oldprop && !$c.and64(u.uprops[FUMBLING].intrinsic, ~TIMEOUT)) {
                $t1 = u.uprops[FUMBLING].extrinsic = 0, u.uprops[FUMBLING].intrinsic = $t1;
            }
            break;
        case GAUNTLETS_OF_POWER:
            await makeknown($G.uarmg.otyp);
            disp.botl = TRUE;   /* taken care of in attrib.c */
            break;
        case GAUNTLETS_OF_DEXTERITY:
            if (!svc.context.takeoff.cancelled_don) {
                await adj_abon($G.uarmg, $c.i8(-$G.uarmg.spe | 0));
            }
            break;
        default:
            await impossible(new $c.Ptr(unknown_type, 0), new $c.Ptr(c_gloves, 0), $G.uarmg.otyp);
    }
    await setworn(null, W.ARMG);
    svc.context.takeoff.cancelled_don = FALSE;
    await encumber_msg();   /* immediate feedback for GoP */
    /* usually can't remove gloves when they're slippery but it can
       be done by having them fall off (polymorph), stolen, or
       destroyed (scroll, overenchantment, monster spell); if that
       happens, 'cure' slippery fingers so that it doesn't transfer
       from gloves to bare hands */
    if (Glib()) {
        await make_glib(0);   /* for update_inventory() */
    }
    /* prevent wielding cockatrice when not wearing gloves */
    if ($G.uwep && $G.uwep.otyp === CORPSE) {
        await wielding_corpse($G.uwep, gloves, on_purpose);
    }
    /* KMH -- ...or your secondary weapon when you're wielding it
       [This case can't actually happen; twoweapon mode won't engage
       if a corpse has been set up as either the primary or alternate
       weapon.  If it could happen and /both/ uwep and uswapwep could
       be cockatrice corpses, life-saving for the first would need to
       prevent the second from being fatal since conceptually they'd
       be being touched simultaneously.] */
    if (u.twoweap && $G.uswapwep && $G.uswapwep.otyp === CORPSE) {
        await wielding_corpse($G.uswapwep, gloves, on_purpose);
    }
    if (condtests[bl_bareh].enabled) {
        disp.botl = TRUE;
    }
    return 0;
}
