            if (!ESleepy() && !$c.and64(u.uprops[SLEEPY].intrinsic, ~TIMEOUT)) {
                u.uprops[SLEEPY].intrinsic = $c.and64(u.uprops[SLEEPY].intrinsic, ~TIMEOUT);   /* clear timeout bits */
            }
